export const LINUX_DISTROS = RAW_DISTROS.map((distro) => ({
  ...distro,
  ...(DISTRO_ASSETS[distro.id] || {}),
  ...(DISTRO_FACTS[distro.id] || {})
}));

export const DISTRO_MAP = {};
LINUX_DISTROS.forEach(d => { DISTRO_MAP[d.id] = d; });
